    [1223263] = { en = "Increased Polearms +$s1.", description = "Aumentata abilità con armi in asta +$s1." },
    [1223687] = { en = "+$s1 Attack Power against Undead.\r\n", description = "+$s1 alla potenza d'attacco contro i Non morti.\r\n" },
    [1223689] = { en = "While applied to target two-handed weapon it increases attack power against undead by $1223687s1. Lasts for 1 hour.", description = "Quando applicato a un'arma a due mani bersaglio, aumenta la potenza d'attacco contro i non morti di $1223687s1. Dura 1 ora." },
    [1223739] = { en = "Unlocks your potential while inside Naxxramas.  Increasing your threat caused by ${$m1/100}.2%, your damage by ${$m2/100}.2%, and your health by ${$m3/100}.2% for each piece of Sanctified armor equipped.", description = "Libera il tuo potenziale all'interno di Naxxramas. Aumenta la minaccia generata del ${$m1/100}.2%, i danni inflitti del ${$m2/100}.2% e la salute del ${$m3/100}.2% per ogni pezzo di armatura Sanctified equipaggiato." },
    [1223755] = { en = "Increases all damage you and your pet deal by $s1% while your pet is active.", description = "Aumenta del $s1% tutti i danni inflitti da te e dal tuo famiglio mentre è attivo." },
    [1223758] = { en = "When your pet is under the effects of Bestial Wrath, you also go into a rage causing $s1% additional damage and reducing the Mana cost of all spells and abilities by $s2%. While enraged, you do not feel pity or remorse or fear and you cannot be stopped unless killed.", description = "Quando il tuo famiglio è sotto l'effetto di Bestial Wrath, anche tu entri in collera, infliggendo il $s1% di danni aggiuntivi e riducendo del $s2% il costo in Mana di tutti gli incantesimi e le abilità. Mentre sei in collera, non provi pietà, rimorso o paura e nulla può fermarti, a meno che tu non venga ucciso." },
    [1223974] = { en = "You spoke to a captive druid in the Emerald Dream, but were unable to free the druid or elicit a response.", description = "Hai parlato con un druido prigioniero nel Sogno di Smeraldo, ma non sei riuscito a liberarlo né a ottenere una risposta." },
    [1223982] = { en = "Freed from the Emerald Nightmare.", description = "Liberato dall'Incubo di Smeraldo." },
    [1223984] = { en = "Increases your Attack Power by $s1% of your Intellect.", description = "Aumenta la tua potenza d'attacco di un valore pari al $s1% del tuo intelletto." },
    [1223987] = { en = "Hitting a target with your Serpent Sting ability grants you $s1% and consuming Rapid Killing grants you $s2% of your Mana regeneration while casting for the next $1242512d.", description = "Colpire un bersaglio con la tua abilità Serpent Sting ti conferisce il $s1% e attivare Rapid Killing ti conferisce il $s2% della tua rigenerazione del Mana durante il lancio degli incantesimi per i successivi $1242512d." },
    [1224410] = { en = "While applied to target weapon or shield it increases spell damage against undead by up to 60. Lasts for 1 hour.", description = "Quando applicato all'arma o allo scudo bersaglio, aumenta fino a 60 i danni degli incantesimi contro i non morti. Dura 1 ora." },
    [1224422] = { en = "While applied to target weapon or shield it increases attack power against undead by 100. Lasts for 1 hour.", description = "Quando applicato all'arma o allo scudo bersaglio, aumenta di 100 la potenza d'attacco contro i non morti. Dura 1 ora." },
    [1224553] = { en = "Increases the critical strike chance of your Holy Shock and Holy Light spells by $s1%.", description = "Aumenta del $s1% la probabilità di colpo critico dei tuoi incantesimi Holy Shock e Holy Light." },
    [1224692] = { en = "Increases all healing your spells do by $s1% and all healing you receive by $s2%.", description = "Aumenta del $s1% tutte le cure dei tuoi incantesimi e del $s2% tutte le cure che ricevi." },
    [1224697] = { en = "Increases your total Stamina by $s1% and reduces the cooldown of your Divine Shield, Divine Protection, and Templar's Bulwark spells by ${$m2/-1000} sec.", description = "Aumenta del $s1% la tua resistenza totale e riduce di ${$m2/-1000} sec il tempo di recupero dei tuoi incantesimi Divine Shield, Divine Protection e Templar's Bulwark." },
    [1224716] = { en = "Increases the critical strike chance of your Backstab by $m1% and your Mutilate by $m3%, and gives Backstab a $m2% chance to add an additional Combo Point.", description = "Aumenta del $m1% la probabilità di colpo critico di Backstab e del $m3% quella di Mutilate; inoltre, dà a Backstab una probabilità del $m2% di aggiungere un punto combo aggiuntivo." },
    [1224782] = { en = "Reduces the Energy cost of your Sap and Blind abilities by $m1%.", description = "Riduce del $m1% il costo in energia delle tue abilità Sap e Blind." },
    [1225132] = { en = "Increases the damage and healing of your instant cast spells by $s1%.", description = "Aumenta del $s1% i danni e le cure dei tuoi incantesimi a lancio istantaneo." },
    [1225139] = { en = "Your Mind Flay now deals $s1% more damage, gains $s2 yards increased range, but slows the target's movement speed by ${$s4-($m3)}%.", description = "Mind Flay ora infligge il $s1% di danni in più e ha una portata aumentata di $s2 yard, ma riduce la velocità di movimento del bersaglio del ${$s4-($m3)}%." },
    [1225177] = { en = "Increases all periodic damage done by your Warlock spells by $s1%.", description = "Aumenta del $s1% tutti i danni periodici inflitti dai tuoi incantesimi da stregone." },
    [1225214] = { en = "You heal your pet for $s1% of all spell damage you deal. When you gain Mana from Life Tap, your summoned demon gains $m2% of the Mana you gain.", description = "Curi il tuo famiglio per un valore pari al $s1% di tutti i danni da incantesimo che infliggi. Quando ottieni Mana da Life Tap, il tuo demone evocato ottiene il $m2% del Mana che hai guadagnato." },
    [1225217] = { en = "Increases the Attack Power reduction of your Felhunter's Tainted Blood, the healing of its Devour Magic, and the detection level of its Paranoia by $s1%, and reduces the cooldown of its Spell Lock by ${$m2/-1000} sec.", description = "Aumenta del $s1% la riduzione della potenza d'attacco di Tainted Blood del tuo Felhunter, le cure di Devour Magic e il livello di rilevamento di Paranoia; inoltre, riduce di ${$m2/-1000} sec il tempo di recupero di Spell Lock." },
    [1225228] = { en = "Afflicts the target for $d, causing $s1% of all damage done by the Warlock to other targets to also be dealt to the cursed target. Bane of Havoc is limited to 1 target, and only one Bane per Warlock can be active on any one target.", description = "Maledice il bersaglio per $d, facendo sì che il $s1% di tutti i danni inflitti dallo stregone agli altri bersagli venga inflitto anche al bersaglio maledetto. Bane of Havoc è limitato a 1 bersaglio e ogni stregone può avere attiva solo una Bane su ciascun bersaglio." },
    [1225419] = { en = "A wave of necrotic energy fills the room, completely preventing all healing effects for $d.\r\n", description = "Un'ondata di energia necrotica pervade la stanza, impedendo completamente ogni effetto di cura per $d.\r\n" },
    [1225435] = { en = "You discover $s1% more Scarce materials from Mining, Herbalism, and Skinning.", description = "Trovi il $s1% in più di materiali scarsi estraendo minerali, raccogliendo erbe e scuoiando." },
    [1225451] = { en = "Increases your chance to gain a skill increase from using any primary, secondary, or class-based tradeskill by $s1%.", description = "Aumenta del $s1% la probabilità di ottenere un aumento di abilità usando qualsiasi professione primaria, secondaria o di classe." },
    [1225455] = { en = "While fishing with a Lure active, you have a $s1% chance to catch an extra fish.", description = "Mentre peschi con un'esca attiva, hai una probabilità del $s1% di pescare un pesce aggiuntivo." },
    [1225456] = { en = "You have a $s1% chance to receive 100% increased Merchant's Favor when you turn in a crate to the Azeroth Commerce Authority or Durotar Supply and Logistics.", description = "Hai una probabilità del $s1% di ricevere il 100% in più di Favore del Mercante quando consegni una cassa all'Azeroth Commerce Authority o alla Durotar Supply and Logistics." },
    [1225457] = { en = "Your cooking recipes have a $s1% chance to create an extra result.", description = "Le tue ricette di cucina hanno una probabilità del $s1% di produrre un risultato aggiuntivo." },
    [1225459] = { en = "Reduces the gold price of items from all vendors by $s1%.", description = "Riduce del $s1% il prezzo in oro degli oggetti presso tutti i mercanti." },
    [1225460] = { en = "Materials used by your Engineering, Blacksmithing, Leatherworking, and Tailoring recipes have a $s1% chance per item to be refunded on completing the recipe.", description = "I materiali usati dalle tue ricette di Ingegneria, Forgiatura, Conciatura e Sartoria hanno una probabilità del $s1% per oggetto di essere restituiti al completamento della ricetta." },
    [1225461] = { en = "Extracts crafting materials from good quality or better armor.", description = "Estrae materiali per la creazione da armature di qualità buona o superiore." },
    [1225465] = { en = "Grants a $s1% chance to gain extra results from First Aid recipes and from Alchemy Elixir, Potion, Draught, and Flask recipes.", description = "Conferisce una probabilità del $s1% di ottenere risultati aggiuntivi dalle ricette di Primo Soccorso e dalle ricette di Alchimia per elisir, pozioni, distillati e ampolle." },
    [1225468] = { en = "Gain $s1 increased skill in Skinning, Mining, and Herbalism, and $s2 increased skill in Fishing.", description = "Ottieni $s1 punti abilità aggiuntivi in Scuoiatura, Estrazione e Erbalismo e $s2 punti abilità aggiuntivi in Pesca." },
    [1225469] = { en = "Increases your skill by 1 in your lowest tradeskill among your Primary and Secondary tradeskills. If you have already reached 300 skill in your two current Primary Tradeskills and all three Secondary Tradeskills, you will gain $s1 of a random Elemental Essence.", description = "Aumenta di 1 la tua abilità nella professione con il livello più basso tra le tue professioni primarie e secondarie. Se hai già raggiunto 300 punti abilità nelle tue due professioni primarie attuali e in tutte e tre le professioni secondarie, otterrai $s1 Essenza elementale casuale." },
    [1225470] = { en = "Craft an Essence of Innovation and research a new recipe for a non-gathering Primary tradeskill in which you have reached 300 skill.", description = "Crea un'Essenza dell'Innovazione e ricerca una nuova ricetta per una professione primaria che non sia di raccolta e in cui hai raggiunto 300 punti abilità." },
    [1225472] = { en = "You gain $s1% of your maximum Health and Mana over $1261483d each time you deliver the killing blow to a non-trivial enemy. Ineffective in dungeons, raids, and battlegrounds.", description = "Ottieni il $s1% della tua salute e del tuo Mana massimi nell'arco di $1261483d ogni volta che infliggi il colpo di grazia a un nemico non banale. Inefficace nei dungeon, nelle incursioni e nei campi di battaglia." },
    [1225474] = { en = "You gain talent points every level starting at level $s1 instead of starting at level 10, but you still may not have more than 51 total talent points.", description = "Ottieni punti talento a ogni livello a partire dal livello $s1, invece che dal livello 10, ma non puoi comunque avere più di 51 punti talento totali." },
    [1225475] = { en = "Reduces the duration of the Recently Bandaged effect by ${$m1/-1000} sec when you use a bandage. Ineffective in dungeons, raids, and battlegrounds.", description = "Riduce di ${$m1/-1000} sec la durata dell'effetto Bendato di recente quando usi una benda. Inefficace nei dungeon, nelle incursioni e nei campi di battaglia." },
    [1225477] = { en = "Increases your ability to detect nearby targets with Stealth as if your level were increased by ${$m1/5}. Ineffective in Battlegrounds.", description = "Aumenta la tua capacità di individuare i bersagli furtivi nelle vicinanze come se il tuo livello fosse superiore di ${$m1/5}. Inefficace nei campi di battaglia." },
    [1225478] = { en = "Your rested experience accumulates $s1% faster and your rested experience cap is increased by $s2%.", description = "L'esperienza di riposo si accumula il $s1% più velocemente e il limite dell'esperienza di riposo aumenta del $s2%." },
    [1225479] = { en = "Reduces your cooldown on adding Camp features by ${$m1/-36000}%", description = "Riduce del ${$m1/-36000}% il tempo di recupero per aggiungere caratteristiche al campo." },
    [1225484] = { en = "Dark magic lashes out at every enemy, inflicting $s1 Shadow damage", description = "La magia oscura si abbatte su ogni nemico, infliggendo $s1 danni da ombra." },
    [1225485] = { en = "Increases your reputation gains by $s1%.", description = "Aumenta del $s1% i punti reputazione ottenuti." },
    [1225487] = { en = "Reduces your cooldown for using potions by ${$m1/-1000} sec. Ineffective in dungeons, raids, and battlegrounds.", description = "Riduce di ${$m1/-1000} s il tempo di recupero per l'uso delle pozioni. Inefficace nei dungeon, nelle incursioni e nei campi di battaglia." },
    [1225490] = { en = "You receive a $s1% discount on all flight paths, and your flight path mount flies $s2% faster.", description = "Ottieni uno sconto del $s1% su tutti i percorsi di volo e la tua cavalcatura volante vola $s2% più velocemente." },
    [1225491] = { en = "Your underwater breath lasts $s1% longer than normal and you swim $s2% faster.", description = "Il tuo respiro sott'acqua dura il $s1% in più del normale e nuoti il $s2% più velocemente." },
    [1225492] = { en = "Gives you a $s1% chance of being able to resurrect with $1261698s1% Health and Mana. Ineffective in dungeons, raids, and battlegrounds. This effect cannot trigger more often than once every $1261707d.", description = "Hai una probabilità del $s1% di poter essere resuscitato con il $1261698s1% della Salute e del Mana. Inefficace nei dungeon, nelle incursioni e nei campi di battaglia. Questo effetto non può attivarsi più spesso di una volta ogni $1261707d." },
    [1225493] = { en = "All innkeepers can now also grant you access to your bank. This access has a $1261854d cooldown.", description = "Ora tutti gli osti possono anche darti accesso alla banca. Questo accesso ha un tempo di recupero di $1261854d." },
    [1225494] = { en = "Returns you to the rest area where you most recently set your Second Home. When used in a rest area, makes that location your Second Home. This ability shares a cooldown with Hearthstones.", description = "Ti riporta all'area di riposo in cui hai impostato più di recente la tua Seconda Casa. Se usata in un'area di riposo, rende quella località la tua Seconda Casa. Questa abilità condivide il tempo di recupero con le Pietre del Ritorno." },
    [1225497] = { en = "You take $s1% less durability loss when you die.", description = "Quando muori, perdi il $s1% in meno di durabilità." },
    [1225498] = { en = "Increases speed while mounted by $s1%. Not active in battlegrounds. Does not stack with other effects that increase mounted movement speed.", description = "Aumenta la velocità in sella del $s1%. Non attivo nei campi di battaglia. Non si cumula con altri effetti che aumentano la velocità di movimento in sella." },
    [1225499] = { en = "Increases the duration of beneficial effects from eating food by $s1%.", description = "Aumenta del $s1% la durata degli effetti benefici derivanti dal cibo." },
    [1225500] = { en = "Increases movement speed while dead by $s1% and your helpful spells and abilities cost no resources for ${$m2/60000} min after being resurrected or until you enter combat.", description = "Aumenta del $s1% la velocità di movimento da morto e, per ${$m2/60000} min dopo essere stato resuscitato o fino a quando non entri in combattimento, i tuoi incantesimi e le tue abilità di supporto non costano risorse." },
    [1225501] = { en = "Increases Honor Points gained by $s1%.", description = "Aumenta i punti Onore ottenuti del $s1%." },
    [1225502] = { en = "Your class abilities which grant long-duration stat or attribute benefits to all party or raid members last $s1% longer, and the benefits you gain from resting at a camp last $s2% longer.", description = "Le abilità di classe che conferiscono benefici di lunga durata alle statistiche o agli attributi a tutti i membri del gruppo o dell'incursione durano il $s1% in più, e i benefici ottenuti riposando in un accampamento durano il $s2% in più." },
    [1225504] = { en = "Increases the duration of beneficial effects from elixirs and flasks by $s1%.", description = "Aumenta del $s1% la durata degli effetti benefici di elisir e ampolle." },
    [1225505] = { en = "You recover an additional ${$m1/10}.1% of your Health and Mana every 5 sec while not in combat.", description = "Quando non sei in combattimento, recuperi un ulteriore ${$m1/10}.1% della Salute e del Mana ogni 5 s." },
    [1225506] = { en = "Beneficial effects you gain from celebrating the defeat of bosses gain $s1% increased duration.", description = "Gli effetti benefici ottenuti celebrando la sconfitta dei boss durano il $s1% in più." },
    [1225508] = { en = "Effects gained from celebrating the defeat of bosses will not cancel the first time you die while they are active.", description = "Gli effetti ottenuti celebrando la sconfitta dei boss non si annullano la prima volta che muori mentre sono attivi." },
    [1225841] = { en = "Curses the target with recklessness, increasing melee attack power by $s1 but reducing armor by $s2 for $d.  Cursed enemies will not flee and will ignore Fear and Horror effects.  Only one Curse per Warlock can be active on any one target.", description = "Maledice il bersaglio con sconsideratezza, aumentando la potenza d'attacco in mischia di $s1 ma riducendo l'armatura di $s2 per $d.  I nemici maledetti non fuggono e ignorano gli effetti di Paura e Terrore.  Ogni Stregone può avere attiva una sola Maledizione su ciascun bersaglio." },
    [1225906] = { en = "Serve a delicious feast that lasts for $d and serves up to $M2 players.\r\n\r\n$@spellicon1225774 $@spellname1225774\r\n$@spelldesc1225774", description = "Prepara un delizioso banchetto che dura $d e serve fino a $M2 giocatori.\r\n\r\n$@spellicon1225774 $@spellname1225774\r\n$@spelldesc1225774" },
    [1225907] = { en = "Serve a delicious feast that lasts for $d and serves up to $M2 players.\r\n\r\n$@spellicon1225774 $@spellname1225774\r\n$@spelldesc1225774", description = "Prepara un delizioso banchetto che dura $d e serve fino a $M2 giocatori.\r\n\r\n$@spellicon1225774 $@spellname1225774\r\n$@spelldesc1225774" },
