    [1226001] = { en = "$@spelldesc1226007", description = "$@spelldesc1226007" },
    [1226007] = { en = "Disrupt a magnetic field between you and your nearby enemy target, knocking you both away.\r\n\r\nCan only affect targets up to $s1 levels higher than you. Some targets cannot be displaced. Targets can only be affected by this effect once every $1226045d.", description = "Interrompe il campo magnetico tra te e il nemico bersaglio nelle vicinanze, respingendo entrambi.\r\n\r\nPuò influenzare solo bersagli fino a $s1 livelli più alti di te. Alcuni bersagli non possono essere spostati. Questo effetto può influenzare i bersagli solo una volta ogni $1226045d." },
    [1226013] = { en = "$@spelldesc1226007", description = "$@spelldesc1226007" },
