    [1226211] = { en = "Augment your belt to give the following effect:\r\n\r\n$@spelldesc1225982\r\n\r\n$?pc138518[This enhancement is permanent and cannot be removed or replaced.][]", description = "Modifica la tua cintura per conferirle il seguente effetto:\r\n\r\n$@spelldesc1225982\r\n\r\n$?pc138518[Questo potenziamento è permanente e non può essere rimosso o sostituito.][]" },
    [1226212] = { en = "Augment your belt to give the following effect:\r\n\r\n$@spelldesc1226001\r\n\r\n$?pc138518[This enhancement is permanent and cannot be removed or replaced.][]", description = "Modifica la tua cintura per conferirle il seguente effetto:\r\n\r\n$@spelldesc1226001\r\n\r\n$?pc138518[Questo potenziamento è permanente e non può essere rimosso o sostituito.][]" },
    [1226981] = { en = "Damage done by you or your summoned demon has a $426301h% chance to increase the damage done by the other by $426303s1% for $426303d. ", description = "I danni inflitti da te o dal tuo demone evocato hanno una probabilità del $426301h% di aumentare i danni inflitti dall'altro del $426303s1% per $426303d. " },
