    [1228366] = { en = "Gives the caster $s1 extra $lattack:attacks;.", description = "Conferisce all'incantatore $s1 $lattacco:attacchi; aggiuntivi." },
    [1228370] = { en = "Deals weapon damage to all enemy targets within $a1 yards.\r\n", description = "Infligge danni da arma a tutti i nemici entro $a1 m.\r\n" },
    [1228372] = { en = "Drops a pool of tar for $d that slows the movement speed of enemies within.", description = "Lascia una pozza di catrame per $d che rallenta la velocità di movimento dei nemici al suo interno." },
    [1229045] = { en = "Increases your maximum health, damage dealt, and happiness when you pet Pupper.", description = "Aumenta la tua salute massima, i danni inflitti e la felicità quando accarezzi Pupper." },
    [1229305] = { en = "Summon Climhazzard, Mount of the High Commander.  Speed is increased by $s2%.", description = "Evoca Climhazzard, cavalcatura dell'Alto Comandante.  La velocità è aumentata del $s2%." },
    [1229308] = { en = "Summons and dismisses a rideable Scarlet Steed.  This is a very fast mount.", description = "Evoca e congeda un destriero scarlatto cavalcabile.  È una cavalcatura molto veloce." },
    [1229340] = { en = "Attempt to make contact with the Will of The Ashbringer.", description = "Tenta di entrare in contatto con la Volontà di The Ashbringer." },
    [1229402] = { en = "Teaches you how to augment your belts with reusable tinkers.", description = "Ti insegna a modificare le cinture con congegni riutilizzabili." },
    [1229409] = { en = "The suffusion of light chokes and smothers you, dealing Holy damage every $t1 seconds.", description = "L'infusione di luce ti soffoca e ti opprime, infliggendo danni sacri ogni $t1 s." },
    [1229432] = { en = "Craft a Camp Tent.", description = "Crea una tenda da accampamento." },
    [1229503] = { en = "Judged by the power of the Ashbringer.", description = "Giudicato dal potere di The Ashbringer." },
    [1229508] = { en = "Judged by the power of the Ashbringer. Stunned, and armor and dodge chance are reduced.", description = "Giudicato dal potere di The Ashbringer. Stordito; armatura e probabilità di schivata ridotte." },
    [1229517] = { en = "Craft a Camp Chair.", description = "Crea una sedia da accampamento." },
    [1229705] = { en = "Craft an Incense Candle.", description = "Crea una candela d'incenso." },
    [1229737] = { en = "Craft a Basic Campfire.", description = "Crea un falò da accampamento semplice." },
    [1229745] = { en = "Craft a Fish Bowl.", description = "Crea una boccia per pesci." },
    [1229760] = { en = "Deal significant physical damage to a trespasser and stun them for $d. ", description = "Infligge ingenti danni fisici a un intruso e lo stordisce per $d. " },
    [1230086] = { en = "Threaten to put the target in stocks, causing them to run in fear for $d.", description = "Minaccia di mettere il bersaglio alla gogna, facendolo fuggire terrorizzato per $d." },
    [1230099] = { en = "Inflicts $s1% of weapon damage to enemies in front of the caster, and causes a Searing Wound on the caster's primary target.\r\n", description = "Infligge ai nemici di fronte all'incantatore danni pari al $s1% dei danni dell'arma e causa una Ferita Bruciante al bersaglio primario dell'incantatore.\r\n" },
    [1230102] = { en = "Deals $1230099s1 damage every $1230102t1 sec for $1230102d. Stacks.", description = "Infligge $1230099s1 danni ogni $1230102t1 sec per $1230102d. Cumulabile." },
    [1230105] = { en = "Calls the might of the wild creating fissures that erupt dealing damage to nearby foes in front of the caster", description = "Invoca la potenza della natura, creando fenditure che eruttano e infliggono danni ai nemici vicini di fronte all'incantatore" },
    [1230117] = { en = "Craft a First Aid Kit.", description = "Crea un Kit di Pronto Soccorso." },
    [1230123] = { en = "Deals $s1 Nature damage to enemies in the blast.", description = "Infligge $s1 danni da Natura ai nemici nell'esplosione." },
    [1230161] = { en = "Craft a Lodestone.", description = "Crea una Pietra Calamita." },
    [1230171] = { en = "Craft a Sharpening Wheel.", description = "Crea una Rotella per Affilare." },
    [1230200] = { en = "Inflicts $s2 Nature damage to an enemy and increases the Nature damage it takes by $s1% for $d.\r\n", description = "Infligge $s2 danni da Natura a un nemico e aumenta i danni da Natura che subisce del $s1% per $d.\r\n" },
    [1230203] = { en = "Deal $s1 Holy damage to the target and increase their damage dealt by $s2%.", description = "Infliggi $s1 danni sacri al bersaglio e aumenta i danni che infligge del $s2%." },
    [1230206] = { en = "Snuff out the target's inner flame, dealing $s1% of their maximum health as Holy Damage per stack of Incite Holy Flame. Survivors will suffer.", description = "Spegni la fiamma interiore del bersaglio, infliggendo danni sacri pari al $s1% della sua salute massima per ogni accumulo di Incitare la Fiamma Sacra. I sopravvissuti soffriranno." },
    [1230215] = { en = "Smite an enemy for $s1 Holy damage. Heal for $s2% of the damage dealt.", description = "Colpisci un nemico infliggendo $s1 danni sacri. Rigeneri salute pari al $s2% dei danni inflitti." },
    [1230228] = { en = "Heal the enemy for $s1% of their maximum health, however they will suffer $s2% of their maximum health every $t2 sec until they leave combat.", description = "Rigenera la salute del nemico del $s1% della sua salute massima, ma questi subirà danni pari al $s2% della sua salute massima ogni $t2 sec finché non uscirà dal combattimento." },
    [1230242] = { en = "Inflicts $s2 Fire damage to an enemy and increases the Fire damage it takes by $s1% for $d.\r\n", description = "Infligge $s2 danni da Fuoco a un nemico e aumenta i danni da Fuoco che subisce del $s1% per $d.\r\n" },
    [1230319] = { en = "The death of a companion awakens a surge of energy, increasing damage dealt by $s1% and attack speed by $s3%.\r\n", description = "La morte di un compagno risveglia un'ondata di energia, aumentando i danni inflitti del $s1% e la velocità d'attacco del $s3%.\r\n" },
    [1230538] = { en = "Attempt to make contact with the disembodied voice of The Ashbringer.", description = "Tenta di entrare in contatto con la voce incorporea di The Ashbringer." },
    [1230564] = { en = "Craft a Mana Well.", description = "Crea un Pozzo di Mana." },
    [1230583] = { en = "Briefly reveal and supercharge your prototype magnet in attempt to catch stray metallic objects.", description = "Rivela brevemente e potenzia al massimo il tuo prototipo di magnete nel tentativo di attirare oggetti metallici vaganti." },
    [1230633] = { en = "Calls forth magma eruptions to damage nearby foes.\r\n", description = "Evoca eruzioni di magma che danneggiano i nemici vicini.\r\n" },
    [1230637] = { en = "Deals $s1 Fire damage to enemies in the blast.\r\n", description = "Infligge $s1 danni da Fuoco ai nemici nell'esplosione.\r\n" },
    [1230638] = { en = "Deals damage to enemies in the blast.\r\n", description = "Infligge danni ai nemici nell'esplosione.\r\n" },
    [1230643] = { en = "Craft an Enchanted Lute.", description = "Crea un Liuto Incantato." },
    [1230656] = { en = "Craft a Reagent Bot.", description = "Crea un Bot Reagenti." },
    [1230671] = { en = "Combine the Emblem of the Ashbringer, Reforged Blade of the Ashbringer, and the Hilt of the Ashbringer. ", description = "Combina l'Emblema di The Ashbringer, la Lama Riforgiata di The Ashbringer e l'Impugnatura di The Ashbringer. " },
    [1230897] = { en = "Maximum health reduced by $S1%.", description = "Salute massima ridotta del $S1%." },
    [1230944] = { en = "Playing the didgeridoo summons a random beast to your side, increasing your physical abilities for $d.  May only be used while in combat.", description = "Suonare il didgeridoo evoca una bestia casuale al tuo fianco, aumentando le tue capacità fisiche per $d. Si può usare solo durante il combattimento." },
    [1230980] = { en = "Throw down the Standard of Stiltz, increasing the maximum health of all nearby allies by $1231903s1 for $d.", description = "Piantare lo Stendardo di Stiltz aumenta la salute massima di tutti gli alleati vicini di $1231903s1 per $d." },
    [1230992] = { en = "You feel a sickening feeling. Turn back now!", description = "Provi una sensazione nauseante. Torna indietro, adesso!" },
    [1231010] = { en = "Vishas marks enemy players. When a marked target casts a spell, Vishas throws a knife in their direction.", description = "Vishas marca i giocatori nemici. Quando un bersaglio marcato lancia un incantesimo, Vishas gli scaglia un coltello." },
    [1231011] = { en = "Vishas throws one of his daggers toward an enemy dealing $s2 Shadow damage to the first enemy it hits. If the knife hits a player afflicted with Tortuous Rebuke, it also adds a bleed.", description = "Vishas scaglia uno dei suoi pugnali verso un nemico, infliggendo $s2 danni da Ombra al primo nemico colpito. Se il coltello colpisce un giocatore affetto da Rimprovero Tortuoso, applica anche un effetto di sanguinamento." },
    [1231024] = { en = "Attempt to use a Portiporter yourself to see what the fuss is about.\r\n\r\nCan only be used in New Avalon and after ensuring relative safety with other test subjects.", description = "Tenta di usare tu stesso un Portiporter per scoprire di cosa si tratta.\r\n\r\nSi può usare solo a New Avalon e dopo essersi assicurati che gli altri soggetti di prova siano relativamente al sicuro." },
    [1231091] = { en = "Insert a variable amount of gunpowder into the device and press the button.\r\n\r\nYour speed and likelihood of serious injury or death will increase based on the amount of gunpowder added.\r\n\r\nCan only be used in New Avalon.", description = "Inserisci una quantità variabile di polvere da sparo nel dispositivo e premi il pulsante.\r\n\r\nLa tua velocità e la probabilità di ferirti gravemente o morire aumenteranno in base alla quantità di polvere da sparo aggiunta.\r\n\r\nSi può usare solo a New Avalon." },
    [1231095] = { en = "Assault the target's mind, inflicting $s1 Shadow damage and increasing Shadow damage taken by $s2 for $d.\r\n", description = "Assalta la mente del bersaglio, infliggendo $s1 danni da Ombra e aumentando i danni da Ombra subiti di $s2 per $d.\r\n" },
    [1231123] = { en = "Summon Pepe to join you on your adventures!", description = "Evoca Pepe perché si unisca alle tue avventure!" },
    [1231128] = { en = "Permanently enchant a melee weapon so that often when attacking in melee it heals for $1231124s2 and increases Strength by $1231124s1 for $1231124d.", description = "Incanta permanentemente un'arma da mischia: spesso, quando attacchi in mischia, ti cura di $1231124s2 e aumenta la tua Forza di $1231124s1 per $1231124d." },
    [1231139] = { en = "Permanently enchant a two-handed melee weapon so that often when striking with a spell it restores $1231138s2 mana and increases Spell Power by $1231138s1 for $1231138d.", description = "Incanta permanentemente un'arma da mischia a due mani: spesso, quando colpisci con un incantesimo, ripristina $1231138s2 mana e aumenta la Potenza magica di $1231138s1 per $1231138d." },
    [1231164] = { en = "Permanently enchant a melee weapon so that often when striking with a spell it restores $1231162s2 mana and increases Spell Power by $1231162s1 for $1231162d.", description = "Incanta permanentemente un'arma da mischia: spesso, quando colpisci con un incantesimo, ripristina $1231162s2 mana e aumenta la Potenza magica di $1231162s1 per $1231162d." },
    [1231212] = { en = "About to explode in a glorious display of magical aptitude, polymorphing yourself and all nearby allies.", description = "Stai per esplodere in una gloriosa dimostrazione di talento magico, trasformando in pecora te stesso e tutti gli alleati vicini." },
    [1231245] = { en = "\r\n\r\n", description = "\r\n\r\n" },
    [1231254] = { en = "Increase Defense by $s1 and Armor by $s2 for $d.", description = "Aumenta la Difesa di $s1 e l'Armatura di $s2 per $d." },
    [1231258] = { en = "Chance on melee attack to inflict your enemy with a rot, dealing $1231261s1 Nature damage every $1231261t1 sec to all enemies within an $1231261a1 yard radius of the caster for $1231261d. The attack speed of these targets is also slowed by $1231261s2%.", description = "Con gli attacchi in mischia, hai una probabilità di infliggere al nemico un'infezione marcescente, che infligge $1231261s1 danni da Natura ogni $1231261t1 sec a tutti i nemici entro $1231261a1 metri dall'incantatore per $1231261d. Anche la velocità d'attacco di questi bersagli è ridotta del $1231261s2%." },
    [1231267] = { en = "Firing a regular ranged attack at a target prepares you for battle, increasing your Defense by $1231266s1 and melee attack speed by $1231266s2% for $1231266d.", description = "Attaccare un bersaglio con un normale attacco a distanza ti prepara alla battaglia, aumentando la Difesa di $1231266s1 e la velocità d'attacco in mischia del $1231266s2% per $1231266d." },
    [1231272] = { en = "Throw spoiled food at the target to deal physical damage.", description = "Lancia cibo avariato al bersaglio per infliggere danni fisici." },
    [1231280] = { en = "Root an enemy to the ground for $d and deal $s1% of their maximum health every $t1 sec.", description = "Immobilizza un nemico al suolo per $d e infligge danni pari al $s1% della sua salute massima ogni $t1 sec." },
    [1231282] = { en = "A pool of lava is conjured inside the Hall of Renewal, flooding the lower level.", description = "Una pozza di lava viene evocata nella Sala del Rinnovamento, inondando il livello inferiore." },
    [1231284] = { en = "Punch the target with rotten fruit in hand, interrupting their spell casting.", description = "Colpisci il bersaglio tenendo in mano della frutta marcia, interrompendo il lancio dei suoi incantesimi." },
    [1231289] = { en = "Invoke the Will of the Mountain, increasing physical damage dealt by $s1%, armor by $s2, and size by $s3% for $d.", description = "Invoca la Volontà della Montagna, aumentando i danni fisici inflitti del $s1%, l'armatura di $s2 e la dimensione del $s3% per $d." },
    [1231293] = { en = "Wave a torch in front of you to deal $s1 Fire damage to up to $x1 targets.\r\n\r\nTargets hit will be set ablaze.", description = "Agita una torcia davanti a te per infliggere $s1 danni da Fuoco a un massimo di $x1 bersagli.\r\n\r\nI bersagli colpiti prenderanno fuoco." },
    [1231297] = { en = "Throw a torch at the enemy to deal $s1 Fire damage.\r\n\r\nSets them ablaze.", description = "Lancia una torcia contro il nemico per infliggere $s1 danni da Fuoco.\r\n\r\nLo incendia." },
    [1231301] = { en = "Suffering $s1% Fire damage every $t1 sec for $d. Stacks up to $U times.\r\n\r\nCaused by New Avalon Watchman abilities when they use their torch.", description = "Subisci $s1% danni da Fuoco ogni $t1 sec per $d. Cumulabile fino a $U volte.\r\n\r\nCausato dalle abilità delle Guardie di New Avalon quando usano la torcia." },
    [1231310] = { en = "Marks the target as an intruder, preventing them from using Stealth, Invisibility, and applying their disguise for $d.", description = "Marchia il bersaglio come intruso, impedendogli di usare Furtività, Invisibilità e di applicare il suo travestimento per $d." },
    [1231317] = { en = "Deal $s1% of the target's maximum health as physical damage and an additional $s2% every $t2 sec for $d.\r\n\r\nUpon expiration, the wound has a chance based on the target's current health to turn into Rabies.", description = "Infligge danni fisici pari al $s1% della salute massima del bersaglio e un ulteriore $s2% ogni $t2 sec per $d.\r\n\r\nAlla scadenza, la ferita ha una probabilità, determinata dalla salute attuale del bersaglio, di trasformarsi in Rabbia." },
    [1231324] = { en = "Movement speed reduced by $s1%. Suffering $s2% maximum health as physical damage every $t2 sec for $d.\r\n\r\nIf left untreated, you will die.", description = "Velocità di movimento ridotta del $s1%. Subisci danni fisici pari al $s2% della salute massima ogni $t2 sec per $d.\r\n\r\nSe non vieni curato, morirai." },
    [1231330] = { en = "Steals $s1 life from up to $x enemies, granting $1231339s2 Strength or Agility per enemy siphoned, stacking up to $1231339u times.", description = "Ruba $s1 punti vita a un massimo di $x nemici, ottenendo $1231339s2 Forza o Agilità per ogni nemico prosciugato, fino a un massimo di $1231339u accumuli." },
    [1231339] = { en = "Strength increased\r\n by $s1 for $d.", description = "Forza aumentata\r\n di $s1 per $d." },
    [1231342] = { en = "$@spelldesc1231343", description = "$@spelldesc1231343" },
    [1231343] = { en = "Shades of Balnazzar strike players that aren't within $1231342A1 yards of another player, inflicting $1231645s1 Shadow damage.", description = "Le Ombre di Balnazzar colpiscono i giocatori che non si trovano entro $1231342A1 metri da un altro giocatore, infliggendo $1231645s1 danni da ombra." },
    [1231380] = { en = "If you remain in Cat Form for $1231381t seconds, increase your Energy Regeneration by $1231381s1%.", description = "Se rimani in Forma Felina per $1231381t secondi, aumenta la tua rigenerazione di energia di $1231381s1%." },
    [1231381] = { en = "If you remain in Cat Form for $t seconds, increase your Energy Regeneration by $s1%, and the damage of your Ferocious Bite by $s2%.", description = "Se rimani in Forma Felina per $t secondi, aumenta la tua rigenerazione di energia di $s1% e i danni del tuo Morso Feroce di $s2%." },
    [1231382] = { en = "Remaining in Cat Form for $1231381t seconds, causes your Energy Regeneration to increase by $1231381s1%.", description = "Rimanere in Forma Felina per $1231381t secondi aumenta la tua rigenerazione di energia del $1231381s1%." },
    [1231397] = { en = "Inflicts $s1 physical damage to an enemy, reducing its movement speed by $s2% for $d.", description = "Infligge $s1 danni fisici a un nemico, riducendone la velocità di movimento del $s2% per $d." },
    [1231399] = { en = "Deal $s1 Shadow damage and increases the target's critical damage received by $s2% per stack, up to $U times.", description = "Infligge $s1 danni da ombra e aumenta i danni critici subiti dal bersaglio del $s2% per accumulo, fino a $U accumuli." },
    [1231400] = { en = "Teleport the target to the New Avalon Town Hall and deal $s1% of their maximum health as shadow damage.", description = "Teletrasporta il bersaglio al Municipio di New Avalon e gli infligge danni da ombra pari al $s1% della sua salute massima." },
    [1231401] = { en = "Bribe the target, ensuring your personal safety.", description = "Corrompi il bersaglio, garantendo la tua sicurezza personale." },
    [1231404] = { en = "Striking a higher level enemy applies a stack of Coup, increasing their damage taken from your next Execute by $1231416s1% or Envenom by $1231424s1% per stack. At $1231416u stacks, Execute may be cast regardless of the target's health.", description = "Colpire un nemico di livello superiore applica un accumulo di Coup, aumentando i danni che subisce dal tuo prossimo Esecuzione del $1231416s1% o dal tuo prossimo Avvelenamento del $1231424s1% per accumulo. A $1231416u accumuli, Esecuzione può essere lanciata indipendentemente dalla salute del bersaglio." },
    [1231417] = { en = "$?s446658[Striking a higher level enemy applies a stack of Coup, increasing their damage taken from your next Execute by $1231416s1% per stack, stacking up to $1231416u times. At $1231416u stacks, Execute may be cast regardless of the target's health.]?s21184[Striking a higher level enemy applies a stack of Coup, increasing their damage taken from your next Envenom by $1231424s1% per stack, stacking up to $1231424u times.]?s446374[Striking a higher level enemy applies a stack of Coup, increasing their damage taken from your next Kill Shot by $1231765s1% per stack, stacking up to $1231765u times.][The blade does not respond to your presence.]", description = "$?s446658[Colpire un nemico di livello superiore applica un accumulo di Coup, aumentando i danni che subisce dal tuo prossimo Esecuzione del $1231416s1% per accumulo, fino a $1231416u accumuli. A $1231416u accumuli, Esecuzione può essere lanciata indipendentemente dalla salute del bersaglio.]?s21184[Colpire un nemico di livello superiore applica un accumulo di Coup, aumentando i danni che subisce dal tuo prossimo Avvelenamento del $1231424s1% per accumulo, fino a $1231424u accumuli.]?s446374[Colpire un nemico di livello superiore applica un accumulo di Coup, aumentando i danni che subisce dal tuo prossimo Tiro Mortale del $1231765s1% per accumulo, fino a $1231765u accumuli.][La lama non reagisce alla tua presenza.]" },
    [1231431] = { en = "Throw an apple, dealing $s1 physical damage and stunning the target for $d.", description = "Lancia una mela, infliggendo $s1 danni fisici e stordendo il bersaglio per $d." },
    [1231433] = { en = "Pull a retreating enemy toward you.", description = "Attira verso di te un nemico in fuga." },
    [1231434] = { en = "$@spelldesc1231433", description = "$@spelldesc1231433" },
    [1231435] = { en = "$@spelldesc1231433", description = "$@spelldesc1231433" },
    [1231444] = { en = "Consume a delicious, hand-picked apple to restore $s1% of your maximum health instantly and another $s2% every $t2 sec for $d.", description = "Consuma una deliziosa mela raccolta a mano per ripristinare istantaneamente il $s1% della tua salute massima e un ulteriore $s2% ogni $t2 secondi per $d." },
    [1231488] = { en = "Pull an enemy out of an unreachable location.", description = "Estrai un nemico da una posizione irraggiungibile." },
    [1231489] = { en = "$@spelldesc1231488", description = "$@spelldesc1231488" },
    [1231490] = { en = "$@spelldesc1231488", description = "$@spelldesc1231488" },
    [1231492] = { en = "Damaging finishing moves have a $b1% chance per combo point to restore $1231491s1 energy.", description = "Le mosse finali che infliggono danni hanno una probabilità del $b1% per punto combo di ripristinare $1231491s1 energia." },
    [1231502] = { en = "Knock back all enemy players in a cone. Enemies that are not knocked back are stunned for $1232842d.", description = "Respinge tutti i giocatori nemici in un cono. I nemici che non vengono respinti sono storditi per $1232842d." },
    [1231507] = { en = "Regular melee attacks inflict enemy players with Thirst of Vis'era.", description = "Gli attacchi in mischia normali infliggono ai giocatori nemici la Sete di Vis'era." },
    [1231509] = { en = "Shame the target for their confessions,  slowing their movement speed by $s1%.", description = "Umilia il bersaglio per le sue confessioni, riducendone la velocità di movimento del $s1%." },
    [1231511] = { en = "Expose the target's sins, breaking a piece of their illegally acquired disguise.", description = "Rivela i peccati del bersaglio, strappandogli un pezzo del travestimento ottenuto illegalmente." },
    [1231541] = { en = "Charge up Vis'era for 1.5 seconds before unleashing the Might of Vis'era, knocking back all enemy players in a cone in front of you.", description = "Carica Vis'era per 1.5 secondi prima di scatenare la Potenza di Vis'era, respingendo tutti i giocatori nemici in un cono di fronte a te." },
    [1231547] = { en = "You attack all nearby enemies for $d causing weapon damage plus an additional $1231546s1 every $t1 sec.", description = "Attacchi tutti i nemici vicini per $d, infliggendo danni dell'arma più altri $1231546s1 ogni $t1 secondi." },
    [1231549] = { en = "Does $s1 additional Holy damage to the target.", description = "Infligge al bersaglio $s1 danni sacri aggiuntivi." },
    [1231550] = { en = "Adds $1231549s1 holy damage to your melee attacks.", description = "Aggiunge $1231549s1 danni sacri ai tuoi attacchi in mischia." },
    [1231586] = { en = "Focus Fire now grants you and your pet $1231591s1% increased damage per stack consumed for $1231591d.", description = "Fuoco Concentrato ora conferisce a te e al tuo famiglio un aumento dei danni del $1231591s1% per ogni accumulo consumato, per $1231591d." },
    [1231589] = { en = "Quench the heated blade in the waters of the Well of Eternity.", description = "Raffredda la lama rovente nelle acque del Pozzo dell'Eternità." },
    [1231590] = { en = "Increases pet's damage done $w1% for $d.", description = "Aumenta i danni inflitti dal famiglio del $w1% per $d." },
    [1231591] = { en = "Increases damage done $w1% for $d.", description = "Aumenta i danni inflitti del $w1% per $d." },
    [1231592] = { en = "Afflicts the target with a curse of the ocean. If the target is not dispelled of the curse, the target will drown.", description = "Colpisce il bersaglio con una maledizione dell'oceano. Se la maledizione non viene dissolta, il bersaglio annegherà." },
    [1231594] = { en = "You drown feeling the lure of the shallow waters.", description = "Anneghi, sedotto dal richiamo delle acque basse." },
    [1231595] = { en = "$h% chance on ranged attack to generate a Strand of Fate, allowing you move and use a ranged attack at the same time. Strands stack up to $1231601u, and last $1231601d.", description = "Probabilità del $h% con un attacco a distanza di generare un Filo del Destino, permettendoti di muoverti e usare un attacco a distanza contemporaneamente. I Fili si accumulano fino a $1231601u e durano $1231601d." },
    [1231604] = { en = "$?a415352[Consume your Strands of Fate, increasing your Strength by $1232969s1 per stack for $1232969d, and causing your next Strike against a non-player controlled target to apply Serpent Sting. Lasts $1232976s1 secs for every stack consumed and cannot be refreshed.][Instantly generate $s1 Strands of Fate.]", description = "$?a415352[Consuma i tuoi Fili del Destino, aumentando la tua Forza di $1232969s1 per accumulo per $1232969d e facendo sì che il tuo prossimo Colpo contro un bersaglio non controllato da un giocatore applichi Pungiglione del Serpente. Dura $1232976s1 secondi per ogni accumulo consumato e non può essere rinnovato.][Genera istantaneamente $s1 Fili del Destino.]" },
    [1231605] = { en = "Transform into a Scarlet Cannon for $d, causing your ranged attacks to explode for $1231607s1 Fire damage to all enemies within $1231607a1 yards of your target.", description = "Ti trasformi in un Cannone Scarlatto per $d, facendo esplodere i tuoi attacchi a distanza e infliggendo $1231607s1 danni da fuoco a tutti i nemici entro $1231607a1 metri dal bersaglio." },
    [1231612] = { en = "Your next regular melee attack made within $d deals Arcane damage equal to $s1 times your spell power, and puts the target to sleep for $d.", description = "Il tuo prossimo attacco in mischia normale effettuato entro $d infligge danni arcani pari a $s1 volte la tua potenza magica e addormenta il bersaglio per $d." },
    [1231614] = { en = "Your next melee attack made within $d deals Arcane damage based on your spell power, and puts the target to sleep for $d.", description = "Il tuo prossimo attacco in mischia effettuato entro $d infligge danni arcani in base alla tua potenza magica e addormenta il bersaglio per $d." },
    [1231620] = { en = "Dealing periodic damage has a $h% chance to grant $1231623s1 spell damage and healing for $1231623d.", description = "Infliggere danni periodici ha una probabilità del $h% di conferire $1231623s1 danni magici e cure per $1231623d." },
    [1231624] = { en = "Dealing non-periodic Fire damage has a $h% chance to increase your Fire damage dealt by $1231625s1% for $1231625d1.", description = "Infliggere danni da fuoco non periodici ha una probabilità del $h% di aumentare i danni da fuoco inflitti del $1231625s1% per $1231625d1." },
    [1231628] = { en = "Chance on landing a damaging spell to create a Mirage on top of your target that deals arcane damage to nearby enemies for $1231629d.", description = "Quando un incantesimo che infligge danni va a segno, ha una probabilità di creare un Miraggio sul bersaglio, che infligge danni arcani ai nemici vicini per $1231629d." },
    [1231636] = { en = "$@spelldesc1231343", description = "$@spelldesc1231343" },
    [1231644] = { en = "$@spelldesc1231343", description = "$@spelldesc1231343" },
    [1231645] = { en = "$@spelldesc1231343", description = "$@spelldesc1231343" },
    [1231646] = { en = "$@spelldesc1231343", description = "$@spelldesc1231343" },
    [1231656] = { en = "The range of your Mind Flay, Fire Blast, and Drain Life spells is increased by $s1 yards, but Mind Flay no longer slows enemies.", description = "La portata degli incantesimi Flagello Mentale, Esplosione di Fuoco e Risucchio Vitale aumenta di $s1 metri, ma Flagello Mentale non rallenta più i nemici." },
    [1231681] = { en = "While above $s1% health, your healing is increased by $1231683s1, but your heals will cause you to sacrifice $1231683s2% of your total health every cast.  While under this effect you may only receive healing from directly targeted, non-periodic heals. (Toggled Effect)", description = "Quando hai più del $s1% di salute, le tue cure aumentano di $1231683s1, ma ogni cura ti fa sacrificare il $1231683s2% della tua salute totale. Sotto questo effetto puoi ricevere cure solo da cure dirette mirate e non periodiche. (Effetto attivabile)" },
    [1231694] = { en = "Damaging spell casts on enemies Condemns them for $1231695d. Whenever they deal damage, their target is healed for $s1% of their maximum health. Lasts $1231695d or up to $1231695u hits. ($proccooldown Secs Cooldown) ", description = "Il lancio di incantesimi che infliggono danni ai nemici li Condanna per $1231695d. Ogni volta che infliggono danni, il loro bersaglio viene curato del $s1% della sua salute massima. Dura $1231695d o fino a $1231695u colpi. (Tempo di recupero: $proccooldown secondi) " },
    [1231698] = { en = "If there are no enemies within $1231708a yards of you, heal all party members within $1231700a yards for $1231700s1 every $1231700t1 seconds. A party may only swear Fealty to one player at a time.", description = "Se non ci sono nemici entro $1231708a metri da te, cura tutti i membri del gruppo entro $1231700a metri di $1231700s1 ogni $1231700t1 secondi. Un gruppo può giurare Fedeltà a un solo giocatore alla volta." },
    [1231708] = { en = "If there are no enemies within $1231700a2 yards of you, heal all nearby party members for $1231700s1 every $1231700t1. A party may only swear Fealty to one player at a time.", description = "Se non ci sono nemici entro $1231700a2 metri da te, cura tutti i membri del gruppo vicini di $1231700s1 ogni $1231700t1. Un gruppo può giurare Fedeltà a un solo giocatore alla volta." },
    [1231776] = { en = "Balnazzar plunges Tyr's Hand into darkness, silencing all players.", description = "Balnazzar avvolge la Mano di Tyr nell'oscurità, silenziando tutti i giocatori." },
    [1231777] = { en = "$@spelldesc1231776", description = "$@spelldesc1231776" },
    [1231806] = { en = "Swap places with your Mirage.", description = "Scambi posto con il tuo Miraggio." },
    [1231836] = { en = "Balnazzar unleashes a swarm of carrion insects that infest players, causing them to inflict $s1 Shadow damage every $t1 sec to allies within $1231837A1 yards for $d. This effect stacks.", description = "Balnazzar scatena uno sciame di insetti necrofagi che infestano i giocatori, facendogli infliggere $s1 danni da Ombra ogni $t1 sec agli alleati entro $1231837A1 metri per $d. Questo effetto si accumula." },
    [1231837] = { en = "$@spelldesc1231836", description = "$@spelldesc1231836" },
    [1231838] = { en = "$@spelldesc1231836", description = "$@spelldesc1231836" },
    [1231839] = { en = "$@spelldesc1231836", description = "$@spelldesc1231836" },
    [1231840] = { en = "$@spelldesc1231836", description = "$@spelldesc1231836" },
    [1231843] = { en = "Balnazzar marks players for domination. After $D players afflicted and allies within $1231845A1 to become charmed for $1231845D.", description = "Balnazzar marchia i giocatori per dominarli. Dopo $D, i giocatori colpiti e gli alleati entro $1231845A1 diventano ammaliati per $1231845D." },
    [1231844] = { en = "$@spellname1231843", description = "$@spellname1231843" },
    [1231845] = { en = "$@spellname1231843\r\n", description = "$@spellname1231843\r\n" },
    [1231874] = { en = "After drinking the experiment, ranged or melee attacks increase your attack speed by $1230943s1% for $d. This effect stacks up to $1230943u times.", description = "Dopo aver bevuto l'esperimento, gli attacchi a distanza o in mischia aumentano la velocità d'attacco del $1230943s1% per $d. Questo effetto si accumula fino a $1230943u volte." },
    [1231883] = { en = "Grants the strength of the Bear for $d.", description = "Conferisce la forza dell'orso per $d." },
    [1231884] = { en = "Grants the accuracy of the owl for $d.", description = "Conferisce la precisione del gufo per $d." },
    [1231886] = { en = "Grants the speed of the cat for $d.", description = "Conferisce la velocità del gatto per $d." },
    [1231888] = { en = "Grants the agility of the raptor for $d.", description = "Conferisce l'agilità del rapace per $d." },
    [1231891] = { en = "Grants the power of the gorilla for $d.", description = "Conferisce la potenza del gorilla per $d." },
    [1231894] = { en = "Grants the ferocity of the crocolisk for $d.", description = "Conferisce la ferocia del crocolisco per $d." },
    [1231896] = { en = "Grants the brilliance of Mr. Bigglesworth for $d.", description = "Conferisce la brillantezza di Mr. Bigglesworth per $d." },
    [1231897] = { en = "$@spelldesc1231898", description = "$@spelldesc1231898" },
    [1231898] = { en = "The infernal burns with a wicked intensity, inflicting $1231897s1 Fire damage to enemies with $A1 yards every $t2 sec, but the light also provides immunity to Suppressive Darkness.", description = "L'infernale arde con una malvagia intensità, infliggendo $1231897s1 danni da Fuoco ai nemici entro $A1 metri ogni $t2 sec, ma la luce conferisce anche immunità a Oscurità Soppressiva." },
    [1231899] = { en = "$@spelldesc1231906", description = "$@spelldesc1231906" },
    [1231900] = { en = "$@spelldesc1231906", description = "$@spelldesc1231906" },
    [1231901] = { en = "$@spelldesc1231906", description = "$@spelldesc1231906" },
    [1231904] = { en = "Increases the amount of damage absorbed by your shield by $s1% for $d.", description = "Aumenta di $s1% i danni assorbiti dal tuo scudo per $d." },
    [1231993] = { en = "Suffering $s2% of your Maximum Health as Radiant damage every $t2 second.", description = "Subisci danni Radianti pari al $s2% della tua Salute massima ogni $t2 secondo." },
    [1232009] = { en = "You have Solistrasza's undivided attention.", description = "Hai tutta l'attenzione di Solistrasza." },
    [1232014] = { en = "The presence of the Ashbringer empowers the Scarlet Crusade.", description = "La presenza di Ashbringer potenzia la Crociata Scarlatta." },
    [1232018] = { en = "The air burns and peels your skin, dealing heavy Fire damage every $t2 second.", description = "L'aria brucia e ti scortica la pelle, infliggendo ingenti danni da Fuoco ogni $t2 secondo." },
    [1232028] = { en = "Lilian Voss' melee attacks strike all players in front of her within $A1 yards.", description = "Gli attacchi in mischia di Lilian Voss colpiscono tutti i giocatori di fronte a lei entro $A1 metri." },
    [1232030] = { en = "Reveal magical crystals.", description = "Rivela cristalli magici." },
    [1232031] = { en = "Reveal magical crystals.\r\n", description = "Rivela cristalli magici.\r\n" },
    [1232033] = { en = "Teleport an intruder somewhere else.", description = "Teletrasporta un intruso altrove." },
    [1232038] = { en = "Shimmer with a mysterious blue energy.", description = "Brilla di una misteriosa energia blu." },
    [1232039] = { en = "Shimmer with a mysterious red energy.", description = "Brilla di una misteriosa energia rossa." },
    [1232040] = { en = "Shimmer with a mysterious violet energy.", description = "Brilla di una misteriosa energia viola." },
    [1232043] = { en = "Lilian Voss senses weakness in her combatants, gaining a stack of $@spellname1232051 for every $s2% total health missing from players.", description = "Lilian Voss percepisce la debolezza dei suoi avversari e ottiene una carica di $@spellname1232051 per ogni $s2% di salute totale mancante ai giocatori." },
    [1232044] = { en = "$h% chance on melee or ranged hit to gain $1232045s1 extra attack.", description = "Probabilità del $h% a ogni colpo in mischia o a distanza di ottenere un attacco extra di $1232045s1." },
    [1232052] = { en = "Improves your chance to get a critical strike with all spells and attacks by $s1%.", description = "Aumenta del $s1% la probabilità di infliggere un colpo critico con tutti gli incantesimi e gli attacchi." },
    [1232066] = { en = "Movement speed Increased by $s1%.", description = "Velocità di movimento aumentata del $s1%." },
    [1232103] = { en = "The Global Cooldown caused by your non-weapon based damaging spells can be reduced by Spell Haste, up to a ${$m1/-1000}.1 second reduction$?s442543[. While equipped you may not have any active Temporal Beacons]?s435395[ while you are not in Metamorphosis]?s440247[, this effect does not apply to Penance]?s435884[ while Way of Earth is not active]?s462814[. This effect does not apply to Holy Shock, and you may not have any active Beacons of Light][].", description = "La ricarica globale causata dagli incantesimi dannosi non basati sulle armi può essere ridotta con Celerità magica, fino a una riduzione di ${$m1/-1000}.1 secondo$?s442543[. Durante l'equipaggiamento, non puoi avere Fari Temporali attivi]?s435395[ se non sei in Metamorfosi]?s440247[, questo effetto non si applica a Penitenza]?s435884[ quando la Via della Terra non è attiva]?s462814[. Questo effetto non si applica a Folgore Sacra e non puoi avere Fari di Luce attivi][]." },
    [1232117] = { en = "Heals the target for $s1, and additionally $s2 every $t2 sec. for $d.", description = "Cura il bersaglio di $s1 e inoltre di $s2 ogni $t2 sec per $d." },
    [1232119] = { en = "$@spelldesc377950\r\n", description = "$@spelldesc377950\r\n" },
    [1232141] = { en = "Shimmer with a mysterious green energy.", description = "Brilla di una misteriosa energia verde." },
    [1232142] = { en = "Shimmer with a mysterious yellow energy.", description = "Brilla di una misteriosa energia gialla." },
    [1232144] = { en = "Shimmer with a mysterious orange energy.", description = "Brilla di una misteriosa energia arancione." },
    [1232146] = { en = "Distract the wizard.", description = "Distrai il mago." },
    [1232172] = { en = "Permanently enchant a two-handed melee weapon so that often when attacking in melee it heals for $1232169s2 and increases Strength by $1232169s1 for $1232169d.", description = "Incanta permanentemente un'arma da mischia a due mani, in modo che spesso, quando attacchi in mischia, ti curi di $1232169s2 e aumenti la Forza di $1232169s1 per $1232169d." },
    [1232178] = { en = "$@spelldesc1232177", description = "$@spelldesc1232177" },
    [1232180] = { en = "Coming into contact with the light sends the Sreeching Terror into a frenzy, increasing attack and movement speed by $s$%", description = "Il contatto con la luce manda il Terrore Stridente in preda alla frenesia, aumentando la velocità d'attacco e di movimento del $s$%." },
    [1232181] = { en = "$?s446658[Your Bloodthirst, Mortal Strike, Shield Slam, Heroic Strike, and Cleave critical strikes set the duration of your Rend on the target to $11574d]?s21184[Your Backstab, Mutilate, and Saber Slash critical strikes set the duration of your Rupture on the target to $s1 sec and your Crimson Tempest to $s2 sec]?s446374[Your Raptor Strike and Mongoose Bite critical strikes set the duration of your Serpent Sting on the target to $13555d][You will never be worthy enough to benefit from this blade].", description = "$?s446658[I colpi critici di Sete di Sangue, Colpo Mortale, Schianto con lo Scudo, Colpo Eroico e Fendente impostano la durata di Lacerazione sul bersaglio a $11574d]?s21184[I colpi critici di Agguato, Mutilazione e Fendente della sciabola impostano la durata di Rottura sul bersaglio a $s1 sec e quella di Tempesta Cremisi a $s2 sec]?s446374[I colpi critici di Assalto del Raptor e Morso di Mangusta impostano la durata di Puntura di Serpente sul bersaglio a $13555d][Non sarai mai abbastanza degno da beneficiare di questa lama]." },
    [1232184] = { en = "$?s21184[Damaging finishing moves have a $1231492b1% chance per combo point to restore $1231491s1 energy.]?s446658[If Cleave hits fewer than its maximum number of targets, it deals $1232185s1% more damage for each unused bounce.]?s446374[Flanking Strike's damage buff is increased by an additional $1232186s2% per stack. When striking from behind, your target takes $1232186s1% increased damage from Flanking Strike.][The blades will never accept you as their master.]", description = "$?s21184[Le mosse finali che infliggono danni hanno una probabilità del $1231492b1% per punto combo di ripristinare $1231491s1 energia.]?s446658[Se Fendente colpisce meno bersagli del numero massimo, infligge $1232185s1% di danni aggiuntivi per ogni rimbalzo inutilizzato.]?s446374[Il bonus ai danni di Assalto Fiancheggiante aumenta di un ulteriore $1232186s2% per carica. Quando colpisci alle spalle, il bersaglio subisce il $1232186s1% di danni aggiuntivi da Assalto Fiancheggiante.][Le lame non ti accetteranno mai come padrone.]" },
    [1232187] = { en = "$@spelldesc437846", description = "$@spelldesc437846" },
    [1232190] = { en = "$@spelldesc1232192", description = "$@spelldesc1232192" },
    [1232191] = { en = "$@spelldesc1232192", description = "$@spelldesc1232192" },
    [1232192] = { en = "Lilian Voss uses her imbued blades to strike her target twice, inflicting $1232191s1 Physical damage and absorbing $s1 healing taken with each hit.", description = "Lilian Voss usa le sue lame infuse per colpire due volte il bersaglio, infliggendo $1232191s1 danni fisici e assorbendo le cure ricevute per $s1 a ogni colpo." },
    [1232193] = { en = "Stabilize the Wing and String by combining it with an Inescapable Fate.", description = "Stabilizza l'Ala e la Corda combinandole con un Destino Ineluttabile." },
    [1232218] = { en = "Now is not the time for petty squabbles.", description = "Non è il momento per meschine dispute." },
    [1232244] = { en = "You have approached a magical ward without your Scarlet Uniform and triggered its defenses.", description = "Ti sei avvicinato a una protezione magica senza la tua Uniforme Scarlatta e ne hai attivato le difese." },
    [1232312] = { en = "The weight of Caladboulder knocks down all nearby enemies for $d.", description = "Il peso di Caladboulder abbatte tutti i nemici vicini per $d." },
    [1232322] = { en = "The earth once again swallow up Caladbolg for $d, decreasing movement speed by $s3%. If moving, your speed increases every $t2 seconds. Smashing into an enemy deals $1232323s2 fire damage, knocks back all nearby enemy players, and ends this effect.", description = "La terra inghiotte ancora una volta Caladbolg per $d, riducendo la velocità di movimento del $s3%. Se ti muovi, la tua velocità aumenta ogni $t2 secondi. Schiantarsi contro un nemico infligge $1232323s2 danni da fuoco, respinge tutti i giocatori nemici vicini e termina questo effetto." },
    [1232345] = { en = "Add the Torn Page to Putress' Diary.", description = "Aggiungi la Pagina strappata al diario di Putress." },
    [1232349] = { en = "Add the First Page to Putress' Diary.", description = "Aggiungi la Prima pagina al diario di Putress." },
    [1232351] = { en = "Add the Second Page to Putress' Diary.", description = "Aggiungi la Seconda pagina al diario di Putress." },
    [1232352] = { en = "Add the Third Page to Putress' Diary.", description = "Aggiungi la Terza pagina al diario di Putress." },
    [1232353] = { en = "Add the Fourth Page to Putress' Diary.", description = "Aggiungi la Quarta pagina al diario di Putress." },
    [1232355] = { en = "Add the Fifth Page to Putress' Diary.", description = "Aggiungi la Quinta pagina al diario di Putress." },
    [1232356] = { en = "Add the Sixth, and Final, Page to Putress' Diary.", description = "Aggiungi la Sesta e ultima pagina al diario di Putress." },
    [1232378] = { en = "A teleporter malfunction has resulted in a new body!", description = "Un malfunzionamento del teletrasporto ti ha procurato un nuovo corpo!" },
    [1232393] = { en = "With the hopes of the righteous you traverse the weave to the New Avalon Monastery.", description = "Con la speranza dei giusti, attraversi il tessuto fino al Monastero di New Avalon." },
    [1232438] = { en = "Combine $s2 fragments to repair the Crusader's Chalice.", description = "Combina $s2 frammenti per riparare il Calice del Crociato." },
    [1232702] = { en = "Sends a wave of force in front of the warrior, causing Physical damage and stunning all enemy targets within $a1 yards in a frontal cone for $d.", description = "Sprigiona un'ondata di forza davanti al guerriero, infliggendo danni fisici e stordendo tutti i bersagli nemici entro $a1 metri in un cono frontale per $d." },
    [1232703] = { en = "Causes $s1 Holy damage to any creature that strikes the target. The aura lasts $d.", description = "Infligge $s1 danni sacri a qualsiasi creatura colpisca il bersaglio. L'aura dura $d." },
    [1232893] = { en = "Your next $u instances of Nature damage are increased by $s1%.  Lasts $d.", description = "I tuoi prossimi $u attacchi che infliggono danni naturali sono potenziati del $s1%. Dura $d." },
    [1232896] = { en = "You may cast Rebirth and Innervate while in Cat Form.", description = "Puoi lanciare Rinascita e Innervazione in Forma felina." },
    [1232946] = { en = "$?a415352[$1232958h% chance on melee attack to generate a Strand of Fate, increasing your Strength by $1232959s1. Stacks up to $1232959u, and lasts $1232959d.][$1231595h% chance on ranged attack to generate a Strand of Fate, allowing you move and use a ranged attack at the same time. Strands stack up to $1231601u, and last $1231601d.]", description = "$?a415352[$1232958h% di probabilità con un attacco in mischia di generare un Filo del Fato, aumentando la tua Forza di $1232959s1. Si accumula fino a $1232959u volte e dura $1232959d.][$1231595h% di probabilità con un attacco a distanza di generare un Filo del Fato, permettendoti di muoverti e usare un attacco a distanza contemporaneamente. I Fili si accumulano fino a $1231601u volte e durano $1231601d.]" },
    [1233078] = { en = "Launches a magical missile at an enemy, inflicting Radiant damage.", description = "Lancia un missile magico contro un nemico, infliggendo danni radiosi." },
    [1233079] = { en = "Launches magical missiles at an enemy, inflicting Radiant damage each second for $d.", description = "Lancia missili magici contro un nemico, infliggendo danni radiosi ogni secondo per $d." },
    [1233293] = { en = "Unleashes an intimidating $@spellname1233293 inflicting $s1 Physical damage to all players.\r\n\r\nThis shout inspires nearby crusaders, increasing their damage done by $s2% for $d.", description = "Scatena un minaccioso $@spellname1233293, infliggendo $s1 danni fisici a tutti i giocatori.\r\n\r\nQuesto grido ispira i crociati nelle vicinanze, aumentando i danni che infliggono del $s2% per $d." },
    [1233451] = { en = "Your next Multi-Shot deals $s1% increased damage.", description = "Il tuo prossimo Tiro multiplo infligge il $s1% di danni aggiuntivi." },
    [1233551] = { en = "$@spelldesc455859", description = "$@spelldesc455859" },
    [1234040] = { en = "$?a435395|a435884[Improves your chance to hit with all spells and attacks by $460230s1%.][Reduces the chance for your attacks to be dodged or parried by $1213289s1%.]", description = "$?a435395|a435884[Aumenta del $460230s1% la probabilità di colpire con tutti gli incantesimi e gli attacchi.][Riduce del $1213289s1% la probabilità che i tuoi attacchi vengano schivati o parati.]" },
    [1234299] = { en = "The Global Cooldown of your Exorcism and Holy Wrath spells is reduced by ${$m1/-1000}.1 seconds.", description = "Il tempo di recupero globale dei tuoi incantesimi Esorcismo e Ira sacra è ridotto di ${$m1/-1000}.1 secondi." },
    [1234318] = { en = "The damage increases from Mercy's and Crimson Cleaver's effects are increased by $s1%.", description = "L'aumento dei danni fornito dagli effetti di Misericordia e Fendente Cremisi è incrementato del $s1%." },
    [1234326] = { en = "The Global Cooldown of your Shock, Lightning, and Lava Burst spells is reduced by ${$m1/-1000}.1 seconds.", description = "Il tempo di recupero globale dei tuoi incantesimi Folgore, Fulmine e Esplosione di lava è ridotto di ${$m1/-1000}.1 secondi." },
    [1234584] = { en = "$@spelldesc1231836", description = "$@spelldesc1231836" },
    [1234598] = { en = "Imbue with wild magic.", description = "Impreziosisce con magia selvaggia." },
    [1234805] = { en = "$?a435395|a435884[Improves your chance to hit with all spells and attacks by $460230s1%.][Reduces the chance for your attacks to be dodged or parried by $1213289s1%.]", description = "$?a435395|a435884[Aumenta del $460230s1% la probabilità di colpire con tutti gli incantesimi e gli attacchi.][Riduce del $1213289s1% la probabilità che i tuoi attacchi vengano schivati o parati.]" },
    [1234895] = { en = "Victory!", description = "Vittoria!" },
    [1235126] = { en = "Returns you to Light's Hope Chapel.", description = "Ti riporta alla Cappella della Luce Fatua." },
    [1235316] = { en = "Increases the effectiveness of your Demon Skin and Demon Armor spells by $m1%.", description = "Aumenta l'efficacia dei tuoi incantesimi Pelle demoniaca e Armatura demoniaca del $m1%." },
    [1235320] = { en = "$?a435884[Chance on hit to cause your next $1232893u instances of Nature damage to be increased by $1231456s1%.  Lasts $1232893d.]?a446658[Chance on hit to cause your next $1235336u instances of Cleave damage to be increased by $1235337s1%. Lasts $1235336d.]?a446374[Chance on hit to cause your next $1235341u instances of Raptor Strike damage to be increased by $1235344s1%. Lasts $1235341d.]?a462814[Chance on hit to cause your next $1235348u instances of Holy damage to be increased by $1235349s1%. Lasts $1235348d.][The Crimson Cleaver does not respond to your presence, maybe another class could benefit from this?]", description = "$?a435884[Probabilità, quando colpisci, che i tuoi prossimi $1232893u attacchi che infliggono danni naturali siano potenziati del $1231456s1%. Dura $1232893d.]?a446658[Probabilità, quando colpisci, che i tuoi prossimi $1235336u attacchi che infliggono danni da Fendente siano potenziati del $1235337s1%. Dura $1235336d.]?a446374[Probabilità, quando colpisci, che i tuoi prossimi $1235341u attacchi che infliggono danni da Assalto del Raptor siano potenziati del $1235344s1%. Dura $1235341d.]?a462814[Probabilità, quando colpisci, che i tuoi prossimi $1235348u attacchi che infliggono danni sacri siano potenziati del $1235349s1%. Dura $1235348d.][La Lama Cremisi non reagisce alla tua presenza, forse un'altra classe potrebbe trarne beneficio?]" },
    [1235336] = { en = "Your next $u instances of Cleave damage are increased by $s1%.  Lasts $d.", description = "I tuoi prossimi $u attacchi che infliggono danni da Fendente sono potenziati del $s1%. Dura $d." },
    [1235341] = { en = "Your next $u instances of Raptor Strike damage are increased by $s1%.  Lasts $d.", description = "I tuoi prossimi $u attacchi che infliggono danni da Assalto del Raptor sono potenziati del $s1%. Dura $d." },
    [1235348] = { en = "Your next $u instances of Holy damage are increased by $s1%.  Lasts $d.", description = "I tuoi prossimi $u attacchi che infliggono danni sacri sono potenziati del $s1%. Dura $d." },
    [1235351] = { en = "$?a435884[Chance on hit to cause your next $1235353u instances of Fire damage to be increased by $1232890s1%. Lasts $1235353d.]?a446658[Chance on hit to cause your next $1235355u instances of Whirlwind damage to be increased by $1235357s1%. Lasts $1235355d.]?a446374[Chance on hit to cause your next $1235359u instances of damage from your pet's special abilities to be increased by $1235361s1%. Lasts $1235359d.][]", description = "$?a435884[Probabilità, quando colpisci, che i tuoi prossimi $1235353u attacchi che infliggono danni da fuoco siano potenziati del $1232890s1%. Dura $1235353d.]?a446658[Probabilità, quando colpisci, che i tuoi prossimi $1235355u attacchi che infliggono danni da Turbine siano potenziati del $1235357s1%. Dura $1235355d.]?a446374[Probabilità, quando colpisci, che i tuoi prossimi $1235359u attacchi che infliggono danni dalle abilità speciali del tuo famiglio siano potenziati del $1235361s1%. Dura $1235359d.][]" },
    [1235353] = { en = "Your next $u instances of Fire damage are increased by $s1%.  Lasts $d.", description = "I tuoi prossimi $u attacchi che infliggono danni da fuoco sono potenziati del $s1%. Dura $d." },
    [1235355] = { en = "Your next $u instances of Whirlwind damage are increased by $s1%.  Lasts $d.", description = "I tuoi prossimi $u attacchi che infliggono danni da Turbine sono potenziati del $s1%. Dura $d." },
    [1235681] = { en = "Increases the damage caused by your Ferocious Bite by $s1%.", description = "Aumenta del $s1% i danni inflitti dal tuo Morso feroce." },
