    [1236266] = { en = "Creates $s1 Explosive Sheep that $lcharges:charge; the nearest $lenemy:enemies; and $lexplodes:explode;. Explosive Sheep are unstable and will self-destruct after $d.", description = "Crea $s1 Pecore esplosive che $lcaricano:carica; $lil nemico più vicino:i nemici più vicini; e $lesplodono:esplode;. Le Pecore esplosive sono instabili e si autodistruggono dopo $d." },
    [1236340] = { en = "A chilling, magical darkness washes over you... ", description = "Un'oscurità magica e gelida ti avvolge... " },
