    [1237152] = { en = "Imbues your weapon with Shadow, increasing your spell haste by $1237162s2% and the damage done by your Shadow spells by up to $1237162s1.", description = "Imbeve la tua arma di ombra, aumentando la celerità degli incantesimi del $1237162s2% e i danni inflitti dai tuoi incantesimi d'ombra fino a $1237162s1." },
    [1237156] = { en = "Imbues your weapon with Shadow, increasing your spell haste by $1237164s2% and the damage done by your Shadow spells by up to $1237164s1.", description = "Imbeve la tua arma di ombra, aumentando la celerità degli incantesimi del $1237164s2% e i danni inflitti dai tuoi incantesimi d'ombra fino a $1237164s1." },
    [1237159] = { en = "Imbues your weapon with Shadow, increasing your spell haste by $1237165s2% and the damage done by your Shadow spells by up to $1237165s1.", description = "Imbeve la tua arma di ombra, aumentando la celerità degli incantesimi del $1237165s2% e i danni inflitti dai tuoi incantesimi d'ombra fino a $1237165s1." },
    [1237268] = { en = "Reduces the mana cost of your Consecration, Holy Wrath, Exorcism, and Hammer of Wrath spells by $m1%.", description = "Riduce del $m1% il costo in mana dei tuoi incantesimi Consacrazione, Ira sacra, Esorcismo e Martello dell'ira." },
    [1238122] = { en = "$?a5487|a9634[|CFFFFFFFFRequires Bear Form, Dire Bear Form|R][|CFFFF2020Requires Bear Form, Dire Bear Form|R]\r\nCharge an enemy, immobilizing them and interrupting any spell they are casting for $19675d.\r\n\r\n$@spelltooltip414924", description = "$?a5487|a9634[|CFFFFFFFFRichiede Forma d'orso, Forma d'orso feroce|R][|CFFFF2020Richiede Forma d'orso, Forma d'orso feroce|R]\r\nCarica un nemico, immobilizzandolo e interrompendo qualsiasi incantesimo stia lanciando per $19675d.\r\n\r\n$@spelltooltip414924" },
    [1238149] = { en = "Increases damage done by your Lightning Shield by $s1%.", description = "Aumenta del $s1% i danni inflitti dal tuo Scudo di fulmini." },
    [1238640] = { en = "Turns the Shaman into a Ghost Wolf, increasing speed by $s2%.", description = "Trasforma lo Sciamano in un Lupo fantasma, aumentando la velocità del $s2%." },
    [1240287] = { en = "Charge an enemy, generate $/10;s2 Rage, and Stun it for $7922d.", description = "Carica un nemico, genera $/10;s2 rabbia e lo stordisce per $7922d." },
    [1240288] = { en = "Charge an enemy, generate $/10;s2 Rage, and Stun it for $7922d.", description = "Carica un nemico, genera $/10;s2 rabbia e lo stordisce per $7922d." },
    [1240289] = { en = "Charge an enemy, generate $/10;s2 Rage, and Stun it for $7922d.", description = "Carica un nemico, genera $/10;s2 rabbia e lo stordisce per $7922d." },
    [1240375] = { en = "Profession", description = "Professione" },
    [1240571] = { en = "While Shock and Awe is active, Crusader Strike and Exorcism grant you Holy Power, increasing all Holy damage you deal by $1226461s1%, stacking up to $1226461u times.", description = "Finché Shock and Awe è attivo, Colpo del Crociato ed Esorcismo ti conferiscono potere sacro, aumentando tutti i danni sacri che infliggi del $1226461s1%, fino a $1226461u accumuli." },
    [1240573] = { en = "Consuming Holy Power increases your Spell Power by $1240574s1% per Holy Power consumed for $1240574d.", description = "Consumare potere sacro aumenta la tua potenza magica del $1240574s1% per ogni punto di potere sacro consumato per $1240574d." },
    [1240692] = { en = "The Fel Ancient sends noxious vines toward an enemy inflicting $1240706s1 Nature damage to enemies within 5 yds and creating poisonous fumes at the location that deal $1263985s1 Nature damage every $1263985t1 sec for $1240707d.", description = "L'Antico Vil invia viti tossiche verso un nemico, infliggendo $1240706s1 danni da natura ai nemici entro 5 m e creando vapori velenosi sul luogo, che infliggono $1263985s1 danni da natura ogni $1263985t1 secondi per $1240707d." },
    [1240706] = { en = "$@spelldesc1240692", description = "$@spelldesc1240692" },
    [1240707] = { en = "$@spelldesc1240692", description = "$@spelldesc1240692" },
