    [1240721] = { en = "Launches a volley of holy light at the target, causing $1240730s1 Holy damage to an enemy, or $1240724s1 healing to an ally, instantly and every $402261t2 sec for $402261d.", description = "Scaglia una raffica di luce sacra sul bersaglio, infliggendo $1240730s1 danni da Sacro a un nemico oppure curando un alleato di $1240724s1, istantaneamente e ogni $402261t2 sec per $402261d." },
    [1240723] = { en = "Healing for $s1 every $1240732t2 sec. for $1240732d.", description = "Cura di $s1 ogni $1240732t2 sec per $1240732d." },
