    [1240750] = { en = "Hits an enemy with a bolt of draining arcane power that consumes up to $s1 mana.", description = "Colpisce un nemico con un dardo di potere arcano prosciugante che consuma fino a $s1 mana." },
    [1240830] = { en = "Siphoning arcane power.", description = "Assorbe potere arcano." },
    [1240869] = { en = "Transforms an enemy into an animal, forcing it to wander around for up to $d. While wandering, the polymorph cannot attack or cast spells.", description = "Trasforma un nemico in un animale, costringendolo a vagare per un massimo di $d. Durante il vagare, la Polimorfia gli impedisce di attaccare o lanciare incantesimi." },
    [1240921] = { en = "Expels unstable mana in an area directed at a player dealing $s1 Arcane damage.", description = "Espelle mana instabile in un'area diretta verso un giocatore, infliggendo $s1 danni da Arcano." },
    [1241329] = { en = "A malfunction has occurred. Every $t1s arcane energy is released dealing damage to players in a nearby area.", description = "Si è verificato un malfunzionamento. Ogni $t1s viene rilasciata energia arcana che infligge danni ai giocatori nell'area circostante." },
    [1241359] = { en = "Expels a cone of arcane energy in front of itself, inflicting $s1 Arcane damage and knocking back all targets struck.", description = "Espelle un cono di energia arcana davanti a sé, infliggendo $s1 danni da Arcano e respingendo tutti i bersagli colpiti." },
    [1241501] = { en = "Channels energy forward dealing damage to any targets caught within the blast.", description = "Canalizza energia in avanti, infliggendo danni a tutti i bersagli investiti dall'esplosione." },
    [1241515] = { en = "$@spelldesc1241523", description = "$@spelldesc1241523" },
    [1241523] = { en = "Launches a mana infused orb toward a random player that travels out and returns to it's origin. Players hit are inflicted with $s1 Arcane damage.", description = "Lancia una sfera intrisa di mana verso un giocatore casuale, che si allontana e poi ritorna al punto di partenza. I giocatori colpiti subiscono $s1 danni da Arcano." },
    [1241524] = { en = "$@spelldesc1241523", description = "$@spelldesc1241523" },
    [1241582] = { en = "Instantly attacks with both weapons for $1241585s2% weapon damage plus an additional ${$1241585m1*$1241585m2/100} with each weapon. Damage increased by $m4% against Poisoned targets. Awards $m1 Combo $LPoint:Points;.", description = "Attacca istantaneamente con entrambe le armi, infliggendo il $1241585s2% dei danni dell'arma più ${$1241585m1*$1241585m2/100} aggiuntivi con ciascuna arma. I danni aumentano del $m4% contro i bersagli avvelenati. Fornisce $m1 $Lpunto:punti combo;." },
    [1241584] = { en = "Instantly attacks with both weapons for $1241586s2% weapon damage plus an additional ${$1241586m1*$1241586m2/100} with each weapon. Damage increased by $m4% against Poisoned targets. Awards $m1 Combo $LPoint:Points;.", description = "Attacca istantaneamente con entrambe le armi, infliggendo il $1241586s2% dei danni dell'arma più ${$1241586m1*$1241586m2/100} aggiuntivi con ciascuna arma. I danni aumentano del $m4% contro i bersagli avvelenati. Fornisce $m1 $Lpunto:punti combo;." },
    [1241797] = { en = "Your damaging finishing moves reduce the remaining cooldown of your Adrenaline Rush, Blade Flurry, Evasion, Sprint, and Vanish abilities by $m1 sec per combo point.", description = "Le tue mosse finali che infliggono danni riducono il tempo di recupero rimanente di Scarica d'Adrenalina, Raffica di Lame, Elusione, Scatto e Svanire di $m1 sec per punto combo." },
    [1241821] = { en = "Crate $M1 ore of your choosing.", description = "Cassa $M1 di minerale a tua scelta." },
    [1242512] = { en = "Regenerating Mana while casting.", description = "Rigenera mana durante il lancio degli incantesimi." },
    [1242871] = { en = "Deals $s1 fire damage, then continues to deal minor Solar damage every $t2 second.", description = "Infligge $s1 danni da Fuoco, poi continua a infliggere danni solari minori ogni $t2 secondo." },
    [1242907] = { en = "Inflicts $S1% physical damage to the current enemy target.", description = "Infligge $S1% danni fisici al bersaglio nemico attuale." },
    [1242913] = { en = "Deals moderate Solar damage, then continues to deal minor Solar damage every $t2 second.", description = "Infligge danni solari moderati, poi continua a infliggere danni solari minori ogni $t2 secondo." },
    [1242979] = { en = "Applies an aura that heals for $p1% of maximum health every $t1 for $d1 seconds. ", description = "Applica un'aura che cura del $p1% della salute massima ogni $t1 per $d1 secondi. " },
