    [1243339] = { en = "Afflicts the target for $1225228d, causing $1225228s1% of all damage done by the Warlock to other targets to also be dealt to the cursed target. Bane of Havoc is limited to 1 target, and only one Bane per Warlock can be active on any one target.", description = "Maledice il bersaglio per $1225228d, facendo sì che il $1225228s1% di tutti i danni inflitti dallo Stregone agli altri bersagli venga inflitto anche al bersaglio maledetto. Bane of Havoc può colpire al massimo 1 bersaglio e uno Stregone può mantenere attiva una sola Bane per bersaglio." },
    [1243356] = { en = "Dig up treasure.", description = "Dissotterra un tesoro." },
    [1243960] = { en = "Summon Vek'zol.", description = "Evoca Vek'zol." },
    [1243969] = { en = "$?pc142418[Additionally, experience gained from kills is increased by $s1%.][]", description = "$?pc142418[Inoltre, l'esperienza ottenuta dalle uccisioni aumenta del $s1%.][]" },
    [1243974] = { en = "Deals $S1 fire damage to all enemies within $r yards.", description = "Infligge $S1 danni da Fuoco a tutti i nemici entro $r metri." },
    [1244396] = { en = "Strikes an enemy with a lightning bolt that arcs to another nearby enemy. The spell affects up to $x1 targets, inflicting greater Nature damage to each successive target.\r\n", description = "Colpisce un nemico con un fulmine che rimbalza su un altro nemico nelle vicinanze. L'incantesimo colpisce fino a $x1 bersagli, infliggendo danni da Natura maggiori a ogni bersaglio successivo.\r\n" },
    [1244416] = { en = "Deals $S2 physical damage to all players within $r, stunning them for $d.", description = "Infligge $S2 danni fisici a tutti i giocatori entro $r, stordendoli per $d." },
    [1244482] = { en = "Wielding an improvised and reluctant weapon, increasing damage dealt by $S3% and reducing damaged received by $S2%.\r\n", description = "Impugnando un'arma improvvisata e riluttante, aumenta i danni inflitti del $S3% e riduce i danni subiti del $S2%.\r\n" },
    [1244484] = { en = "Deals $15578s1 physical damage to all players within $15578d1 yards. Also inflicts an aura that slows movement speed by $s2 for $d2.", description = "Infligge $15578s1 danni fisici a tutti i giocatori entro $15578d1 metri. Applica inoltre un'aura che riduce la velocità di movimento di $s2 per $d2." },
    [1244625] = { en = "Siphon magic from a Ley Line Rift.", description = "Assorbe magia da una Fenditura della Linea di Ley." },
    [1244896] = { en = "Inflicts $S1 fire damage to all players within $rad% yards.", description = "Infligge $S1 danni da Fuoco a tutti i giocatori entro $rad% metri." },
    [1244951] = { en = "Heals the target by 100% of their maximum health.", description = "Cura il bersaglio del 100% della sua salute massima." },
    [1245119] = { en = "Reduces damage dealt by $s1% for $d.\r\n", description = "Riduce i danni inflitti del $s1% per $d.\r\n" },
    [1245130] = { en = "Dealis fire damage every $p for $d to all players within $rad# yards.", description = "Infligge danni da Fuoco ogni $p per $d a tutti i giocatori entro $rad# metri." },
    [1245154] = { en = "Delivers a powerful roar, stunning all players within $R1 for $d. ", description = "Emette un potente ruggito, stordendo tutti i giocatori entro $R1 per $d. " },
    [1245158] = { en = "Attempt to fetch info about the target item. DNT", description = "Tenta di recuperare informazioni sull'oggetto bersaglio. DNT" },
    [1245164] = { en = "Causes the target to bleed, inflicting $s1 physical damage every $t2 sec for $d.", description = "Fa sanguinare il bersaglio, infliggendo $s1 danni fisici ogni $t2 sec per $d." },
    [1245249] = { en = "Increases Physical damage by $s1 for $d.", description = "Aumenta i danni fisici di $s1 per $d." },
    [1245320] = { en = "Divides 1 pile of Strange Dust into $s1 Motes of Magic.", description = "Divide 1 cumulo di Polvere Strana in $s1 Motte di Magia." },
    [1245338] = { en = "Summons two spirit wolves.", description = "Evoca due lupi spiritici." },
    [1245340] = { en = "$@spelldesc<1245338>", description = "$@spelldesc<1245338>" },
    [1245883] = { en = "Stuns an enemy, preventing it from moving or taking action for $d. Also removes one random buff from the affected enemy.", description = "Stordisce un nemico, impedendogli di muoversi o agire per $d. Rimuove inoltre un potenziamento casuale dal nemico colpito." },
    [1245940] = { en = "Increases haste by $S1%. ", description = "Aumenta la celerità del $S1%. " },
    [1245956] = { en = "Inflicts $S1 Fire damage to the current target.", description = "Infligge $S1 danni da Fuoco al bersaglio attuale." },
    [1246026] = { en = "Aids in healing and growth of verdant vegetation.", description = "Aiuta a guarire e a far crescere la vegetazione rigogliosa." },
    [1246031] = { en = "Causes nearby kobold tracks to appear on your map.", description = "Fa apparire sulla tua mappa le tracce dei kobold nelle vicinanze." },
}
for id, record in pairs(records) do
    local current = ns.data.spellDescriptionOverrides[id]
    if current == nil then
        ns.data.spellDescriptionOverrides[id] = record
    end
end
